  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ==========================================\n// 1. NÚCLEO MULTI-TENANT Y SEGURIDAD\n// ==========================================\nmodel Tenant {\n  id          String   @id @default(uuid())\n  name        String\n  subdomain   String   @unique\n  emailDomain String   @unique // Ej: @cocacola.com\n  themeColor  String?\n  logoUrl     String?\n  createdAt   DateTime @default(now())\n\n  users User[]\n}\n\nmodel Role {\n  id          String @id @default(uuid())\n  name        String // Ej: SUPER_ADMIN, HR_ADMIN, BASIC_USER\n  permissions Json // Define accesos estrictos: { \"hr\": \"write\", \"tickets\": \"all\" }\n  users       User[]\n}\n\nmodel User {\n  id             String @id @default(uuid())\n  numeroEmpleado String @unique // ID de 6 dígitos para el login general\n  email          String @unique // OBLIGATORIO: Correo corporativo\n  password       String // Contraseña encriptada obligatoria\n\n  // Datos básicos para el token y la interfaz visual\n  firstName String\n  lastName  String\n  avatarUrl String?\n\n  tenantId String\n  tenant   Tenant @relation(fields: [tenantId], references: [id])\n\n  roleId String\n  role   Role   @relation(fields: [roleId], references: [id])\n\n  isActive  Boolean  @default(true) // Borrado Lógico (Soft Delete)\n  createdAt DateTime @default(now())\n\n  // Relaciones a Módulos\n  hrProfile HR_Profile?\n  itAssets  IT_Asset[]\n  payrolls  Finance_Payroll[]\n\n  // Relaciones al Helpdesk y Sistema\n  createdTickets  Ticket[]       @relation(\"TicketCreator\")\n  assignedTickets Ticket[]       @relation(\"TicketAssignee\")\n  notifications   Notification[]\n  auditLogs       Audit_Log[]\n\n  @@index([tenantId])\n}\n\n// ==========================================\n// 2. MÓDULOS ERP (Silos de Información)\n// ==========================================\n\nmodel HR_Profile {\n  id     String @id @default(uuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id])\n\n  position     String\n  hireDate     DateTime\n  baseSalary   Decimal  @db.Decimal(10, 2)\n  contractType String\n  documentUrl  String?\n\n  tenantId String\n\n  @@index([tenantId])\n}\n\nmodel IT_Asset {\n  id           String @id @default(uuid())\n  serialNumber String\n  deviceType   String\n  model        String\n  status       String\n\n  assignedToId String?\n  assignedTo   User?   @relation(fields: [assignedToId], references: [id])\n\n  tenantId String\n\n  @@index([tenantId])\n}\n\nmodel Finance_Payroll {\n  id          String   @id @default(uuid())\n  paymentDate DateTime\n  amountNet   Decimal  @db.Decimal(10, 2)\n  status      String\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id])\n\n  tenantId String\n\n  @@index([tenantId])\n}\n\n// ==========================================\n// 3. HELPDESK Y COMUNICACIÓN TRANSVERSAL\n// ==========================================\nenum TicketStatus {\n  PENDING\n  IN_PROGRESS\n  RESOLVED\n  REJECTED\n}\n\nenum Area {\n  HR\n  IT\n  FINANCE\n  GENERAL\n}\n\nmodel Ticket {\n  id            String       @id @default(uuid())\n  title         String\n  description   String       @db.Text\n  status        TicketStatus @default(PENDING)\n  targetArea    Area\n  attachmentUrl String?\n\n  creatorId String\n  creator   User   @relation(\"TicketCreator\", fields: [creatorId], references: [id])\n\n  assignedToId String?\n  assignedTo   User?   @relation(\"TicketAssignee\", fields: [assignedToId], references: [id])\n\n  createdAt  DateTime  @default(now())\n  resolvedAt DateTime?\n\n  tenantId String\n\n  @@index([tenantId])\n}\n\nmodel Notification {\n  id      String  @id @default(uuid())\n  message String\n  isRead  Boolean @default(false)\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id])\n\n  createdAt DateTime @default(now())\n  tenantId  String\n\n  @@index([tenantId])\n}\n\n// ==========================================\n// 4. CAJA NEGRA (Auditoría)\n// ==========================================\nmodel Audit_Log {\n  id        String @id @default(uuid())\n  action    String\n  tableName String\n  recordId  String\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id])\n\n  createdAt DateTime @default(now())\n  tenantId  String\n\n  @@index([tenantId])\n}\n",
